from pathlib import Path
import json, os, sys
from playwright.sync_api import sync_playwright
root=Path(__file__).resolve().parents[2]/'public'
out=Path(__file__).resolve().parents[2]/'test-output/enterprise';out.mkdir(parents=True,exist_ok=True)
checks=[];errors=[]
def check(name,ok=True):
 checks.append({'test':name,'passed':bool(ok)});print(('PASS 'if ok else 'FAIL ')+name,flush=True)
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path=os.environ.get('SENDZAD_CHROMIUM','/usr/bin/chromium'),headless=True,args=['--no-sandbox'])
 page=browser.new_page(viewport={'width':1440,'height':1000})
 page.on('pageerror',lambda e:errors.append(str(e)))
 page.on('dialog',lambda d:d.accept())
 page.route('https://**',lambda r:r.abort())
 css=''.join((root/'assets'/f).read_text() for f in ['workspace.css','enterprise.css'])
 scripts=''.join('<script>'+ (root/'assets'/f).read_text().replace('</script','<\\/script')+'</script>' for f in ['demo.js','enterprise-demo.js']+[p.name for p in sorted((root/'assets').glob('template-catalog.*.js'))]+['templates.js','enterprise.js','workspace-enterprise.js'])
 html='<html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>'+css+'</style></head><body data-preview="true"><div id="app"></div><dialog id="dialog" aria-labelledby="dialog-title"></dialog><div id="toast" hidden></div>'+scripts+'</body></html>'
 page.evaluate("location.hash='templates'");page.set_content(html);page.wait_for_selector('#sz-library')
 page.wait_for_timeout(300)
 check('separate template library',page.get_by_role('heading',name='Templates',exact=True).count()==1)
 page.get_by_role('button',name='+ New template',exact=True).click();page.wait_for_selector('#sz-name')
 page.locator('#sz-name').fill('November newsletter');page.locator('#sz-subject').fill('Your November update')
 page.frame_locator('#sz-frame').locator('h1').click();page.frame_locator('#sz-frame').locator('h1').fill('Useful news, simply delivered.')
 page.get_by_role('button',name='Save template',exact=True).click();page.wait_for_function("document.querySelector('#sz-save-state')?.textContent.startsWith('Saved')")
 check('save creates independent reusable record')
 template_id=page.url.split('/')[-1]
 page.evaluate("location.hash='templates'");page.wait_for_selector('#sz-library table');page.locator('#sz-library a.row-link').first.click();page.wait_for_selector('#sz-name')
 check('saved title survives reopening the saved record',page.locator('#sz-name').input_value()=='November newsletter')
 check('saved content survives reopening the saved record','Useful news' in page.frame_locator('#sz-frame').locator('body').inner_text())
 page.frame_locator('#sz-frame').locator('[data-tz-block="header"] h2').click();page.frame_locator('#sz-frame').locator('[data-tz-block="header"] h2').fill('MY COMPANY')
 page.frame_locator('#sz-frame').locator('[data-tz-block="footer"] p').first.click();page.frame_locator('#sz-frame').locator('[data-tz-block="footer"] p').first.fill('Our edited footer - Lagos')
 page.get_by_role('button',name='Save template',exact=True).click();page.wait_for_timeout(250)
 check('headers and footers editable','Our edited footer' in page.frame_locator('#sz-frame').locator('body').inner_text())
 page.frame_locator('#sz-frame').locator('h1').click();page.wait_for_selector('#sz-property-form')
 page.locator('[name="color"]').fill('#123456');page.get_by_role('button',name='Apply properties',exact=True).click()
 check('property inspector changes text colour',page.frame_locator('#sz-frame').locator('h1').evaluate('(n)=>n.style.color')=='rgb(18, 52, 86)')
 before=page.frame_locator('#sz-frame').locator('[data-tz-block]').count()
 page.locator('#sz-block').select_option('cta-panel');page.get_by_role('button',name='+ Add section',exact=True).click();page.wait_for_timeout(100)
 check('add reusable section',page.frame_locator('#sz-frame').locator('[data-tz-block]').count()==before+1)
 page.frame_locator('#sz-frame').locator('[data-tz-block="cta"] h2').click()
 page.locator('.sz-block-tools [data-sz="block-copy"]').click();page.wait_for_timeout(80)
 check('duplicate section',page.frame_locator('#sz-frame').locator('[data-tz-block]').count()==before+2)
 page.frame_locator('#sz-frame').locator('[data-tz-block="cta"]').first.locator('h2').click()
 page.locator('.sz-block-tools [data-sz="block-remove"]').click();page.wait_for_timeout(80)
 check('remove selected section',page.frame_locator('#sz-frame').locator('[data-tz-block]').count()==before+1)
 page.get_by_role('button',name='Insert content',exact=True).click();page.wait_for_selector('#sz-insert-form')
 page.locator('#sz-insert-form [name=kind]').select_option('image');page.locator('#sz-insert-form [name=label]').fill('Product preview')
 page.locator('#sz-insert-form [name=url]').fill('javascript:bad()');page.locator('#sz-insert-form button[type=submit]').click()
 check('insert rejects unsafe image URL',page.locator('#sz-insert-error').inner_text()!='')
 page.locator('#sz-insert-form [name=url]').fill('https://images.example.org/product.jpg');page.locator('#sz-insert-form button[type=submit]').click();page.wait_for_timeout(100)
 check('insert adds editable image with alternative text',page.frame_locator('#sz-frame').locator('img[alt="Product preview"]').count()==1)
 check('template editor does not contain SMTP settings',page.locator('input[type=password]').count()==0)
 page.get_by_role('button',name='HTML',exact=True).click();page.wait_for_selector('#sz-html')
 check('HTML source editor exposes full header/footer', 'MY COMPANY' in page.locator('#sz-html').input_value() and 'Our edited footer' in page.locator('#sz-html').input_value())
 original=page.locator('#sz-html').input_value();page.locator('#sz-html').fill(original+'<script>window.badTemplate=true</script><img src="x" onerror="alert(1)">')
 page.get_by_role('button',name='Design',exact=True).click();page.wait_for_timeout(150)
 check('design preview removes executable content',page.frame_locator('#sz-frame').locator('script,[onerror]').count()==0)
 page.get_by_role('button',name='Save template',exact=True).click();page.wait_for_timeout(200)
 page.locator('summary').filter(has_text='Actions').first.click();page.get_by_role('button',name='Version history',exact=True).click();page.wait_for_selector('.sz-history')
 check('saved revision history available',page.locator('.sz-history>div').count()>=3)
 page.locator('.sz-history [data-sz="restore-version"]').last.click();page.wait_for_timeout(200)
 check('restore creates new revision',page.locator('#sz-save-state').inner_text().startswith('Saved'))
 page.locator('summary').filter(has_text='Actions').first.click();page.get_by_role('button',name='Create campaign',exact=True).click();page.wait_for_selector('#draft-name')
 check('create campaign copies saved subject',page.locator('#draft-subject').input_value()=='Your November update')
 check('campaign view has no SMTP credentials',page.locator('input[type=password]').count()==0)
 page.evaluate("location.hash="+json.dumps('templates')); page.wait_for_selector('#sz-library table');page.wait_for_timeout(100)
 check('campaign copy does not remove reusable template',page.locator('#sz-library tbody tr').count()==1)
 page.locator('#sz-library summary').click();page.locator('#sz-library [data-sz="duplicate"]').click();page.wait_for_selector('#sz-name')
 check('duplicate is separately editable',page.locator('#sz-name').input_value().endswith('(copy)'))
 page.evaluate("location.hash="+json.dumps('templates')); page.wait_for_selector('#sz-library table')
 page.locator('#sz-library summary').first.click();page.locator('#sz-library [data-sz="archive"]').first.click();page.wait_for_timeout(120)
 check('archive removes template from active list',page.locator('#sz-library tbody tr').count()==1)
 page.evaluate("location.hash="+json.dumps('templates/archived')); page.wait_for_selector('[data-sz="unarchive"]');page.locator('[data-sz="unarchive"]').click();page.wait_for_timeout(120)
 check('unarchive restores saved design',page.get_by_role('heading',name='No archived templates').count()==1)
 for sub in ['smtp','identity','verification','delivery']:
  page.evaluate("location.hash="+json.dumps('email-settings/'+sub));page.wait_for_timeout(150)
  check('dedicated email settings view '+sub,page.get_by_role('heading',name='Email settings',exact=True).count()==1)
  check('active email settings tab '+sub,page.locator('.sz-tabs a[aria-current=page]').count()==1)
 page.evaluate("location.hash="+json.dumps('email-settings/identity')); page.wait_for_selector('#sz-identity-form');page.locator('[name=name]').fill('Sample Studio');page.locator('#sz-identity-form button').click();page.wait_for_timeout(100)
 check('brand settings save independently','saved' in page.locator('#sz-message').inner_text().lower())
 # Reload stored library for screenshots and responsive layouts. No provider calls.
 for width in [360,390,768,1024,1440]:
  page.set_viewport_size({'width':width,'height':1000})
  for route in ['overview','campaigns','templates','email-settings/smtp','email-settings/identity','email-settings/delivery','template-editor/'+template_id]:
   page.evaluate("location.hash="+json.dumps(''+route));page.wait_for_timeout(160)
   overflow=page.evaluate('document.documentElement.scrollWidth>innerWidth+1')
   check(f'no document overflow {width} {route}',not overflow)
 page.set_viewport_size({'width':1440,'height':1000})
 for route,name in [('overview','dashboard'),('templates','templates'),('email-settings/smtp','email-settings'),('template-editor/'+template_id,'template-editor')]:
  page.evaluate("location.hash="+json.dumps(''+route));page.wait_for_timeout(200);page.screenshot(path=str(out/(name+'.png')),full_page=True)
 page.set_viewport_size({'width':390,'height':900});page.evaluate("location.hash="+json.dumps('template-editor/'+template_id));page.wait_for_timeout(200);page.screenshot(path=str(out/'template-editor-mobile.png'),full_page=True)
 check('no uncaught browser errors',not errors)
 (out/'ui-results.json').write_text(json.dumps({'checks':checks,'errors':errors,'scope':'synthetic browser store; not authenticated PHP/MySQL or live send'},indent=2))
 browser.close()
print(json.dumps({'passed':sum(c['passed'] for c in checks),'total':len(checks),'errors':errors}),flush=True)
sys.exit(0 if all(c['passed'] for c in checks) and not errors else 1)
